import subprocess,json

def sql(q):
 return subprocess.check_output(['ssh','s3','sudo mysql -NB isupipe'],input=q.encode()).decode().splitlines()
def api(path):
 return json.loads(subprocess.check_output(['ssh','s2',f'curl -s --resolve pipe.u.isucon.dev:8080:127.0.0.1 -b /tmp/verify-cookies http://pipe.u.isucon.dev:8080{path}']))
subprocess.run(['ssh','s2', '''curl -s --resolve pipe.u.isucon.dev:8080:127.0.0.1 -c /tmp/verify-cookies -H 'Content-Type: application/json' -d '{\"username\":\"test001\",\"password\":\"test\"}' http://pipe.u.isucon.dev:8080/api/login'''],check=True)
streams={int(i):{'owner':int(u),'reactions':0,'comments':0,'tips':0,'max':0,'viewers':0,'reports':0} for i,u in (r.split('\\t') for r in sql('SELECT id,user_id FROM livestreams'))}
users={int(i):n for i,n in (r.split('\\t') for r in sql('SELECT id,name FROM users'))}
for r in sql('SELECT livestream_id,COUNT(*),SUM(tip),MAX(tip) FROM livecomments WHERE deleted=0 GROUP BY livestream_id'):
 i,c,t,m=map(int,r.split('\\t'));streams[i].update(comments=c,tips=t,max=m)
for table,key in [('reactions','reactions'),('livestream_viewers_history','viewers'),('livecomment_reports','reports')]:
 for r in sql(f'SELECT livestream_id,COUNT(*) FROM {table} GROUP BY livestream_id'):
  i,c=map(int,r.split('\\t'))
  if i in streams:streams[i][key]=c
scores={i:s['tips']+s['reactions'] for i,s in streams.items()}
targets=[1,max(scores,key=scores.get),max(streams)]
for i in targets:
 s=streams[i]
 expected=dict(rank=1+sum((v,j)>(scores[i],i) for j,v in scores.items()),viewers_count=s['viewers'],total_reactions=s['reactions'],total_reports=s['reports'],max_tip=s['max'])
 actual=api(f'/api/livestream/{i}/statistics');assert actual==expected,(i,actual,expected)
 print('stream',i,'statistics match')
for uid in set([streams[i]['owner'] for i in targets]):
