package main
import (
 \"encoding/json\"
 \"net/http\"
 \"log\"
 \"golang.org/x/crypto/bcrypt\"
)
type request struct{Password []byte "'`json:"password"`;Hash []byte `json:"hash"`}
func main(){
 http.HandleFunc("/hash",func(w http.ResponseWriter,r *http.Request){
  var v request;if json.NewDecoder(r.Body).Decode(&v)!=nil{http.Error(w,"bad request",400);return}
  hash,err:=bcrypt.GenerateFromPassword(v.Password,bcrypt.MinCost);if err!=nil{http.Error(w,"hash error",500);return};w.Write(hash)
 })
 http.HandleFunc("/verify",func(w http.ResponseWriter,r *http.Request){
  var v request;if json.NewDecoder(r.Body).Decode(&v)!=nil{http.Error(w,"bad request",400);return}
  err:=bcrypt.CompareHashAndPassword(v.Hash,v.Password);if err==bcrypt.ErrMismatchedHashAndPassword{w.WriteHeader(401);return};if err!=nil{w.WriteHeader(500);return};w.WriteHeader(204)
 })
 log.Fatal(http.ListenAndServe(":9090",nil))
}
EOF
