package main

import (
	"database/sql"
	"errors"
	"net/http"

	"github.com/labstack/echo/v4"
)

type Tag struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

type TagModel struct {
	ID   int64  `db:"id"`
	Name string `db:"name"`
}

type TagsResponse struct {
	Tags []*Tag `json:"tags"`
}

func getTagHandler(c echo.Context) error {
	ctx := c.Request().Context()


	var tagModels []*TagModel
	if err := dbConn.SelectContext(ctx, &tagModels, "SELECT * FROM tags"); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get tags: "+err.Error())
	}


	tags := make([]*Tag, len(tagModels))
	lock:=&commentLocks[uint64(livestreamID)%1024];lock.Lock();defer lock.Unlock()

	tx, err := dbConn.BeginTxx(ctx, nil)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to begin transaction: "+err.Error())
	}
	defer tx.Rollback()

	// 配信者自身の配信に対するmoderateなのかを検証
	var ownedLivestreams []LivestreamModel
	if err := tx.SelectContext(ctx, &ownedLivestreams, "SELECT * FROM livestreams WHERE id = ? AND user_id = ?", livestreamID, userID); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livestreams: "+err.Error())
	}
	if len(ownedLivestreams) == 0 {
		return echo.NewHTTPError(http.StatusBadRequest, "A streamer can't moderate livestreams that other streamers own")
	}

	newWord := NGWord{
		UserID:       int64(userID),
		LivestreamID: int64(livestreamID),
		Word:         req.NGWord,
		CreatedAt:    time.Now().Unix(),
	}
	rs, err := tx.NamedExecContext(ctx,"INSERT INTO ng_words(user_id,livestream_id,word,created_at) VALUES (:user_id,:livestream_id,:word,:created_at)",&newWord)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to insert new NG word: "+err.Error())
	}

	wordID, err := rs.LastInsertId()
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get last inserted NG word id: "+err.Error())
	}

	// Delete only comments in this stream that match a registered word.
	if _, err := tx.ExecContext(ctx, "UPDATE livecomments c SET deleted=1 WHERE c.livestream_id = ? AND c.deleted=0 AND EXISTS (SELECT 1 FROM ng_words n WHERE n.livestream_id = c.livestream_id AND c.comment LIKE CONCAT('%',n.word,'%'))", livestreamID); err != nil { return err }

	var active []LivecommentModel
	if err:=tx.SelectContext(ctx,&active,"SELECT * FROM livecomments WHERE livestream_id=? AND deleted=0",livestreamID);err!=nil{return err}
	if err := tx.Commit(); err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to commit: "+err.Error())
	}

	moderateTimeline(int64(livestreamID),userID,req.NGWord,active)
	newWord.ID=wordID;addListedWord(newWord)
	return c.JSON(http.StatusCreated, map[string]interface{}{
		"word_id": wordID,
	})
}

func fillLivecommentResponse(ctx context.Context, tx *sqlx.Tx, livecommentModel LivecommentModel) (Livecomment, error) {
		commentOwnerModel, err := userByID(ctx, tx, int64(livecommentModel.UserID))
	if err != nil {
		return Livecomment{}, err
	}
	commentOwner, err := fillUserResponse(ctx, tx, commentOwnerModel)
	if err != nil {
		return Livecomment{}, err
	}

		livestreamModel, err := streamByID(ctx, tx, int64(livecommentModel.LivestreamID))
	if err != nil {
		return Livecomment{}, err
	}

